```python
def tr_lower(s: str) -> str:
    """Türkçe kurallarına göre küçük harfe çevirir."""
    result = []
    for char in s:
        if char == 'İ':
            result.append('i')
        elif char == 'I':
            result.append('ı')
        else:
            result.append(char.lower())
    return "".join(result)

def tr_upper(s: str) -> str:
    """Türkçe kurallarına göre büyük harfe çevirir."""
    result = []
    for char in s:
        if char == 'i':
            result.append('İ')
        elif char == 'ı':
            result.append('I')
        else:
            result.append(char.upper())
    return "".join(result)

def tr_sorted(words: list[str]) -> list[str]:
    """Türkçe alfabesine göre (büyük/küçük harf farkı gözetmeksizin) sıralanmış yeni bir liste döndürür."""
    alphabet = "0123456789abcçdefgğhıijklmnoöpqrsştuüvwxyz"
    alpha_map = {char: i for i, char in enumerate(alphabet)}

    def get_sort_key(word: str):
        lower_word = tr_lower(word)
        key = []
        for char in lower_word:
            if char in alpha_map:
                key.append((1, alpha_map[char]))
            else:
                key.append((0, ord(char)))
        return key

    return sorted(words, key=get_sort_key)
```

